CREATE TABLE customers(customer_id VARCHAR(10) PRIMARY KEY,first_name VARCHAR(50) NOT NULL,last_name VARCHAR(50) NOT NULL,segment VARCHAR(30) NOT NULL,risk_category VARCHAR(20) NOT NULL,email VARCHAR(120));
CREATE TABLE accounts(account_id VARCHAR(10) PRIMARY KEY,customer_id VARCHAR(10) NOT NULL REFERENCES customers(customer_id),account_type VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL,current_balance DECIMAL(12,2));
CREATE TABLE complaints(complaint_id VARCHAR(10) PRIMARY KEY,customer_id VARCHAR(10) NOT NULL REFERENCES customers(customer_id),account_id VARCHAR(10) REFERENCES accounts(account_id),category VARCHAR(60) NOT NULL,status VARCHAR(20) NOT NULL,date_opened DATE NOT NULL,date_closed DATE,channel VARCHAR(20),priority VARCHAR(10));
CREATE TABLE complaint_status_history(status_event_id SERIAL PRIMARY KEY,complaint_id VARCHAR(10) REFERENCES complaints(complaint_id),status VARCHAR(20) NOT NULL,status_timestamp TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE service_requests(request_id VARCHAR(10) PRIMARY KEY,complaint_id VARCHAR(10) REFERENCES complaints(complaint_id),customer_id VARCHAR(10) REFERENCES customers(customer_id),request_type VARCHAR(60),status VARCHAR(20),created_date DATE NOT NULL);

